function divisors(num) {
    let ret = [];
    for (let i = 2; i * i < num; i++) {
        if (num % i === 0) {
            ret.push(i);
            ret.push(num / i);
        }
    }
    let i = 2;
    while (i * i < num) i++;
    if (i * i === num) {
        ret.push(i);
    }
    return ret;
}

function main() {
    const fs = require('fs');
    let input;
    try {
        input = fs.readFileSync('input.in', 'utf8');
    } catch (e) {
        input = fs.readFileSync(0, 'utf8');
    }
    const output = [];
    const tokens = input.trim().split(/\s+/);
    let idx = 0;
    while (idx + 2 < tokens.length) {
        const n = parseInt(tokens[idx++]);
        const m = parseInt(tokens[idx++]);
        const k = parseInt(tokens[idx++]);

        if (n % 2 === 0) {
            output.push("Marsel");
            continue;
        }

        let div = divisors(m);
        let flag = false;
        if (m > 1) {
            div.push(1);
        }
        for (let i = 0; i < div.length && !flag; i++) {
            if (div[i] >= k) {
                flag = true;
